'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { isAuthenticated, removeToken } from '@/lib/auth';
import { apiClient } from '@/lib/api';

export default function Home() {
  const router = useRouter();
  const [user, setUser] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [token, setToken] = useState<string | null>(null);

  useEffect(() => {
    if (!isAuthenticated()) {
      router.push('/login');
      return;
    }

    // localStorage에서 토큰과 사용자 정보 확인
    const storedToken = localStorage.getItem('access_token');
    const cachedUser = localStorage.getItem('user_data');

    setToken(storedToken);

    if (cachedUser) {
      try {
        setUser(JSON.parse(cachedUser));
        setLoading(false);
      } catch (e) {
        console.error('캐시된 사용자 정보 파싱 실패:', e);
        setLoading(false);
      }
    } else {
      // 사용자 정보가 없으면 로딩만 해제
      setLoading(false);
    }
  }, [router]);

  const handleLogout = async () => {
    try {
      await apiClient.logout();
    } catch (err) {
      console.error('Logout error:', err);
    } finally {
      removeToken();
      localStorage.removeItem('user_data');
      router.push('/login');
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <nav className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <h1 className="text-xl font-bold text-gray-900">논문 관리 시스템</h1>
            <button
              onClick={handleLogout}
              className="px-4 py-2 text-sm text-red-600 hover:text-red-700"
            >
              로그아웃
            </button>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-2xl font-bold text-gray-900 mb-4">
            환영합니다!
          </h2>

          {token && (
            <div className="mb-6 p-4 bg-blue-50 rounded-lg">
              <p className="text-sm font-medium text-blue-900 mb-2">현재 토큰 (테스트용)</p>
              <p className="text-xs text-blue-700 break-all font-mono">{token}</p>
            </div>
          )}

          {user && (
            <div className="space-y-2">
              <p className="text-gray-600">
                <span className="font-medium">이메일:</span> {user.email}
              </p>
              <p className="text-gray-600">
                <span className="font-medium">이름:</span> {user.name}
              </p>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
